#import <UIKit/UIKit.h>
#import <AVFoundation/AVFoundation.h>
#import <Security/Security.h>
#import <objc/runtime.h>

@interface AppDelegate : UIResponder <UIApplicationDelegate>
@property(nonatomic,strong) UIWindow *window;
@end
@interface LibraryController : UITableViewController
@end
@interface PlayerController : UIViewController
- (id)initWithFiles:(NSArray *)files index:(NSUInteger)index;
@end

@implementation AppDelegate
- (BOOL)application:(UIApplication *)application didFinishLaunchingWithOptions:(NSDictionary *)options {
 self.window=[[UIWindow alloc]initWithFrame:[UIScreen mainScreen].bounds]; UIViewController *pin=[UIViewController new]; pin.view.backgroundColor=[UIColor colorWithWhite:.07 alpha:1]; pin.title=@"Private Media Player";
 UILabel *heading=[[UILabel alloc]initWithFrame:CGRectMake(20,110,pin.view.bounds.size.width-40,50)]; heading.autoresizingMask=UIViewAutoresizingFlexibleWidth; heading.text=@"Enter or create your PIN"; heading.textColor=UIColor.whiteColor; heading.textAlignment=NSTextAlignmentCenter; heading.font=[UIFont boldSystemFontOfSize:23]; [pin.view addSubview:heading];
 UITextField *field=[[UITextField alloc]initWithFrame:CGRectMake(45,180,pin.view.bounds.size.width-90,50)]; field.autoresizingMask=UIViewAutoresizingFlexibleWidth; field.backgroundColor=UIColor.whiteColor; field.secureTextEntry=YES; field.keyboardType=UIKeyboardTypeNumberPad; field.textAlignment=NSTextAlignmentCenter; field.placeholder=@"4 or 6 digits"; field.layer.cornerRadius=7; [pin.view addSubview:field];
 UIButton *unlock=[UIButton buttonWithType:UIButtonTypeSystem]; unlock.frame=CGRectMake(45,250,pin.view.bounds.size.width-90,48); unlock.autoresizingMask=UIViewAutoresizingFlexibleWidth; unlock.backgroundColor=[UIColor colorWithRed:.1 green:.45 blue:.85 alpha:1]; unlock.layer.cornerRadius=7; [unlock setTitle:@"Continue" forState:UIControlStateNormal]; [unlock setTitleColor:UIColor.whiteColor forState:UIControlStateNormal]; [pin.view addSubview:unlock];
 UILabel *hint=[[UILabel alloc]initWithFrame:CGRectMake(20,310,pin.view.bounds.size.width-40,60)]; hint.autoresizingMask=UIViewAutoresizingFlexibleWidth; hint.numberOfLines=0; hint.textColor=UIColor.lightGrayColor; hint.textAlignment=NSTextAlignmentCenter; hint.font=[UIFont systemFontOfSize:12]; hint.text=@"First launch saves your PIN in iOS Keychain. Keep it safe; reinstalling the app may require setup again."; [pin.view addSubview:hint];
 __weak typeof(self) weakSelf=self; [unlock addTarget:self action:@selector(noop) forControlEvents:UIControlEventTouchUpInside];
 objc_setAssociatedObject(pin, "pinField", field, OBJC_ASSOCIATION_RETAIN_NONATOMIC); objc_setAssociatedObject(pin,"pinHeading",heading,OBJC_ASSOCIATION_RETAIN_NONATOMIC);
 [unlock addTarget:weakSelf action:@selector(unlockFrom:) forControlEvents:UIControlEventTouchUpInside];
 UINavigationController *nav=[[UINavigationController alloc]initWithRootViewController:pin]; nav.navigationBar.barStyle=UIBarStyleBlack; nav.navigationBar.barTintColor=[UIColor colorWithWhite:.1 alpha:1]; nav.navigationBar.tintColor=UIColor.whiteColor; nav.navigationBar.titleTextAttributes=@{NSForegroundColorAttributeName:UIColor.whiteColor}; self.window.rootViewController=nav; [self.window makeKeyAndVisible]; return YES;
}
- (void)noop {}
- (NSString *)pinValue { NSDictionary *q=@{(__bridge id)kSecClass:(__bridge id)kSecClassGenericPassword,(__bridge id)kSecAttrService:@"PrivateMediaPlayer",(__bridge id)kSecAttrAccount:@"PIN",(__bridge id)kSecReturnData:@YES,(__bridge id)kSecMatchLimit:(__bridge id)kSecMatchLimitOne}; CFTypeRef r=NULL; if(SecItemCopyMatching((__bridge CFDictionaryRef)q,&r)!=errSecSuccess)return nil; NSData *d=CFBridgingRelease(r); return [[NSString alloc]initWithData:d encoding:NSUTF8StringEncoding]; }
- (void)unlockFrom:(UIButton *)button { UIResponder *responder=button; while(responder && ![responder isKindOfClass:UIViewController.class]) responder=responder.nextResponder; UIViewController *pin=(UIViewController *)responder; UITextField *f=objc_getAssociatedObject(pin,"pinField"); UILabel *h=objc_getAssociatedObject(pin,"pinHeading"); NSString *entered=f.text?:@"", *saved=[self pinValue]; if(entered.length!=4&&entered.length!=6){h.text=@"Enter exactly 4 or 6 digits";return;} if(!saved){NSDictionary *q=@{(__bridge id)kSecClass:(__bridge id)kSecClassGenericPassword,(__bridge id)kSecAttrService:@"PrivateMediaPlayer",(__bridge id)kSecAttrAccount:@"PIN",(__bridge id)kSecValueData:[entered dataUsingEncoding:NSUTF8StringEncoding],(__bridge id)kSecAttrAccessible:(__bridge id)kSecAttrAccessibleWhenUnlockedThisDeviceOnly}; SecItemAdd((__bridge CFDictionaryRef)q,NULL);} else if(![saved isEqualToString:entered]){h.text=@"Incorrect PIN. Try again.";f.text=@"";return;} LibraryController *lib=[LibraryController new]; [(UINavigationController *)self.window.rootViewController setViewControllers:@[lib] animated:YES]; }
@end

@implementation LibraryController { NSArray *_media; }
- (NSURL *)docs { return [[[NSFileManager defaultManager]URLsForDirectory:NSDocumentDirectory inDomains:NSUserDomainMask]firstObject]; }
- (void)viewDidLoad { [super viewDidLoad]; self.title=@"My Media"; self.tableView.backgroundColor=[UIColor colorWithWhite:.07 alpha:1]; self.tableView.separatorColor=UIColor.darkGrayColor; self.navigationItem.rightBarButtonItem=[[UIBarButtonItem alloc]initWithTitle:@"Refresh" style:UIBarButtonItemStylePlain target:self action:@selector(refresh)]; UILabel *foot=[[UILabel alloc]initWithFrame:CGRectMake(0,0,self.view.bounds.size.width,75)]; foot.autoresizingMask=UIViewAutoresizingFlexibleWidth; foot.numberOfLines=0; foot.textAlignment=NSTextAlignmentCenter; foot.textColor=UIColor.lightGrayColor; foot.font=[UIFont systemFontOfSize:12]; foot.text=@"Use 3uTools → Apps → Private Media Player → File Sharing to add media. MP4 (H.264/AAC) recommended."; self.tableView.tableFooterView=foot; [self refresh]; }
- (void)refresh { NSArray *all=[[NSFileManager defaultManager]contentsOfDirectoryAtURL:self.docs includingPropertiesForKeys:nil options:NSDirectoryEnumerationSkipsHiddenFiles error:nil]; NSMutableArray *a=[NSMutableArray array]; NSSet *ext=[NSSet setWithArray:@[@"mp4",@"m4v",@"mov",@"jpg",@"jpeg",@"png"]]; for(NSURL *u in all)if([ext containsObject:u.pathExtension.lowercaseString])[a addObject:u]; _media=[a sortedArrayUsingComparator:^NSComparisonResult(NSURL *x,NSURL *y){return [x.lastPathComponent localizedCaseInsensitiveCompare:y.lastPathComponent];}]; [self.tableView reloadData]; }
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return _media.count;}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)p { UITableViewCell *c=[t dequeueReusableCellWithIdentifier:@"m"]; if(!c)c=[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:@"m"]; NSURL *u=_media[p.row]; c.textLabel.text=u.lastPathComponent;c.textLabel.textColor=UIColor.whiteColor;c.detailTextLabel.text=u.pathExtension.uppercaseString;c.detailTextLabel.textColor=UIColor.lightGrayColor;c.backgroundColor=[UIColor colorWithWhite:.07 alpha:1];c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return c; }
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)p { NSURL *u=_media[p.row]; if([@[@"mp4",@"m4v",@"mov"] containsObject:u.pathExtension.lowercaseString]){PlayerController *vc=[[PlayerController alloc]initWithFiles:_media index:p.row];[self.navigationController pushViewController:vc animated:YES];}else{UIImage *im=[UIImage imageWithContentsOfFile:u.path];UIViewController *v=[UIViewController new];v.view.backgroundColor=UIColor.blackColor;UIImageView *iv=[[UIImageView alloc]initWithImage:im];iv.frame=v.view.bounds;iv.autoresizingMask=UIViewAutoresizingFlexibleWidth|UIViewAutoresizingFlexibleHeight;iv.contentMode=UIViewContentModeScaleAspectFit;[v.view addSubview:iv];v.title=u.lastPathComponent;[self.navigationController pushViewController:v animated:YES];}[t deselectRowAtIndexPath:p animated:YES]; }
@end

@implementation PlayerController { NSArray *_files; NSUInteger _index; AVPlayer *_player; AVPlayerLayer *_playerLayer; UISlider *_slider; UILabel *_time; UIButton *_play; id _observer; }
- (id)initWithFiles:(NSArray *)files index:(NSUInteger)i {if((self=[super init])){_files=files;_index=i;}return self;}
- (UIButton *)button:(NSString *)title frame:(CGRect)frame action:(SEL)sel {UIButton *b=[UIButton buttonWithType:UIButtonTypeSystem];b.frame=frame;b.backgroundColor=[UIColor colorWithWhite:.18 alpha:1];b.layer.cornerRadius=7;[b setTitle:title forState:UIControlStateNormal];[b setTitleColor:UIColor.whiteColor forState:UIControlStateNormal];[b addTarget:self action:sel forControlEvents:UIControlEventTouchUpInside];return b;}
- (void)viewDidLoad { [super viewDidLoad];self.view.backgroundColor=UIColor.blackColor;self.title=[_files[_index]lastPathComponent];CGFloat w=self.view.bounds.size.width;UIView *screen=[[UIView alloc]initWithFrame:CGRectMake(0,100,w,w*9/16)];screen.autoresizingMask=UIViewAutoresizingFlexibleWidth;[self.view addSubview:screen];_player=[AVPlayer playerWithURL:_files[_index]];_playerLayer=[AVPlayerLayer playerLayerWithPlayer:_player];_playerLayer.frame=screen.bounds;_playerLayer.videoGravity=AVLayerVideoGravityResizeAspect;[screen.layer addSublayer:_playerLayer];_slider=[[UISlider alloc]initWithFrame:CGRectMake(18,CGRectGetMaxY(screen.frame)+15,w-36,30)];_slider.autoresizingMask=UIViewAutoresizingFlexibleWidth;[_slider addTarget:self action:@selector(seek:) forControlEvents:UIControlEventValueChanged];[self.view addSubview:_slider];_time=[[UILabel alloc]initWithFrame:CGRectMake(18,CGRectGetMaxY(_slider.frame),w-36,22)];_time.textColor=UIColor.whiteColor;_time.font=[UIFont systemFontOfSize:12];[self.view addSubview:_time];CGFloat y=CGRectGetMaxY(_time.frame)+15;[self.view addSubview:[self button:@"◀ Previous" frame:CGRectMake(8,y,112,48) action:@selector(previous)]];_play=[self button:@"Pause" frame:CGRectMake((w-90)/2,y,90,48) action:@selector(toggle)];_play.autoresizingMask=UIViewAutoresizingFlexibleLeftMargin|UIViewAutoresizingFlexibleRightMargin;[self.view addSubview:_play];UIButton *next=[self button:@"Next ▶" frame:CGRectMake(w-120,y,112,48) action:@selector(next)];next.autoresizingMask=UIViewAutoresizingFlexibleLeftMargin;[self.view addSubview:next];[self.view addSubview:[self button:@"↶ 10s" frame:CGRectMake(25,y+65,90,42) action:@selector(back10)]];UIButton *fwd=[self button:@"10s ↷" frame:CGRectMake(w-115,y+65,90,42) action:@selector(forward10)];fwd.autoresizingMask=UIViewAutoresizingFlexibleLeftMargin;[self.view addSubview:fwd];UIButton *q=[self button:@"Resolution / Quality ▾" frame:CGRectMake(25,y+125,w-50,44) action:@selector(quality)];q.autoresizingMask=UIViewAutoresizingFlexibleWidth;[self.view addSubview:q];self.navigationItem.leftBarButtonItem=[[UIBarButtonItem alloc]initWithTitle:@"Back" style:UIBarButtonItemStylePlain target:self action:@selector(close)];__weak typeof(self) weak=self;_observer=[_player addPeriodicTimeObserverForInterval:CMTimeMake(1,1) queue:dispatch_get_main_queue() usingBlock:^(CMTime t){[weak update];}];[_player play]; }
- (void)update {Float64 d=CMTimeGetSeconds(_player.currentItem.duration),c=CMTimeGetSeconds(_player.currentTime);if(isfinite(d)&&d>0){_slider.maximumValue=d;_slider.value=c;}_time.text=[NSString stringWithFormat:@"%02d:%02d / %02d:%02d",(int)c/60,(int)c%60,(int)d/60,(int)d%60];}
- (void)seek:(UISlider *)s {[_player seekToTime:CMTimeMakeWithSeconds(s.value,NSEC_PER_SEC)];}
- (void)toggle {if(_player.rate==0){[_player play];[_play setTitle:@"Pause" forState:UIControlStateNormal];}else{[_player pause];[_play setTitle:@"Play" forState:UIControlStateNormal];}}
- (void)skip:(int)n {Float64 c=CMTimeGetSeconds(_player.currentTime)+n;if(c<0)c=0;[_player seekToTime:CMTimeMakeWithSeconds(c,NSEC_PER_SEC)];}
- (void)back10{[self skip:-10];}- (void)forward10{[self skip:10];}
- (void)load {[_player replaceCurrentItemWithPlayerItem:[AVPlayerItem playerItemWithURL:_files[_index]]];self.title=[_files[_index]lastPathComponent];[_player play];}
- (void)previous{if(_index>0){_index--;[self load];}}- (void)next{if(_index+1<_files.count){_index++;[self load];}}
- (void)quality {UIAlertController *a=[UIAlertController alertControllerWithTitle:@"Resolution" message:@"Select an available pre-encoded file. For Movie.mp4, add Movie_360p.mp4, Movie_480p.mp4, Movie_720p.mp4 or Movie_1080p.mp4. The app does not transcode video." preferredStyle:UIAlertControllerStyleActionSheet];for(NSString *q in @[@"Original",@"360p",@"480p",@"720p",@"1080p"])[a addAction:[UIAlertAction actionWithTitle:q style:UIAlertActionStyleDefault handler:^(UIAlertAction *act){[self setVariant:act.title];}]];[a addAction:[UIAlertAction actionWithTitle:@"Cancel" style:UIAlertActionStyleCancel handler:nil]];if(UI_USER_INTERFACE_IDIOM()==UIUserInterfaceIdiomPad){a.popoverPresentationController.sourceView=self.view;a.popoverPresentationController.sourceRect=CGRectMake(self.view.bounds.size.width/2,self.view.bounds.size.height-60,1,1);}[self presentViewController:a animated:YES completion:nil];}
- (void)setVariant:(NSString *)q {if([q isEqualToString:@"Original"])return;NSURL *u=_files[_index];NSString *base=[u.lastPathComponent stringByDeletingPathExtension];NSRegularExpression *re=[NSRegularExpression regularExpressionWithPattern:@"_(360p|480p|720p|1080p)$" options:NSRegularExpressionCaseInsensitive error:nil];base=[re stringByReplacingMatchesInString:base options:0 range:NSMakeRange(0,base.length) withTemplate:@""];NSString *name=[NSString stringWithFormat:@"%@_%@.%@",base,q,u.pathExtension];NSURL *v=[[u URLByDeletingLastPathComponent]URLByAppendingPathComponent:name];if([[NSFileManager defaultManager]fileExistsAtPath:v.path]){NSMutableArray *m=[_files mutableCopy];m[_index]=v;_files=m;[self load];}else{UIAlertView *alert=[[UIAlertView alloc]initWithTitle:@"Not found" message:[NSString stringWithFormat:@"Import %@ using 3uTools first.",name] delegate:nil cancelButtonTitle:@"OK" otherButtonTitles:nil];[alert show];}}
- (void)close{[_player pause];[self.navigationController popViewControllerAnimated:YES];}
- (void)dealloc{if(_observer)[_player removeTimeObserver:_observer];[_player pause];}
@end

int main(int argc,char *argv[]){@autoreleasepool{return UIApplicationMain(argc,argv,nil,NSStringFromClass([AppDelegate class]));}}
